   won=true;r();W.sfx('success');W.confetti();$('#fb').innerHTML=`<div class="tip"><b class="t">✅ Sintaks valid — algoritma benar! +${sm.xp} XP</b></div>${darkCode('pseudocode.algo',placed.map(p=>'    '.repeat(p.i)+p.t).join('\n'))}<b style="display:block;margin-top:10px">Uji input simulasi</b><div class="row" style="margin-top:6px">${sm.tests.map((t,i)=>`<button class="chip blk2" data-t="${i}">${esc(t.l)}</button>`).join('')}</div><div id="to" class="mt"></div>`;
